"""Small statistics helpers used by the orders service."""


def median(values):
    if not values:
        raise ValueError("median() requires at least one value")
    if len(values) % 2 == 1:
        return values[len(values) // 2]
    return (values[len(values) // 2 - 1] + values[len(values) // 2]) / 2


def mean(values):
    if not values:
        raise ValueError("mean() requires at least one value")
    return sum(values) / len(values)

"""Order-line pricing for the storefront."""


def apply_discount(price, quantity, percent):
    """Return the discounted total for one order line."""
    return price * quantity * (1 - percent / 100)

"""Warehouse stock operations."""

STOCK = {"widget": 12, "gear": 0}


def order(item, count):
    available = STOCK[item]
    if count > available:
        raise RuntimeError(f"insufficient stock for {item!r}")
    STOCK[item] = available - count
    return STOCK[item]

