"""Split a command line into argument tokens."""


def split_args(line):
    """Split `line` into arguments, honoring double quotes."""
    parts = []
    current = ""
    for ch in line:
        if ch == " ":
            parts.append(current)
            current = ""
        elif ch == '"':
            continue
        else:
            current += ch
    parts.append(current)
    return parts

export interface Shape {
  kind: "circle" | "square";
  size: number;
}

export function area(shape: Shape): number {
  if (shape.kind === "circle") {
    return 3.14159 * shape.size * shape.size;
  }
  return shape.size * shape.size;
}

export function describe(shape: Shape): string {
  const label: string = shape.kind === "circle" ? "circle" : 7;
  return `a ${label} with area ${area(shape)}`;
}

