setTimeout(() => {
  assert.strictEqual(cache.get("a"), undefined, "entry must expire after ttl");
  cache.set("b", 2);
  assert.strictEqual(cache.get("b"), 2);
  console.log("test_kv_cache: all assertions passed");
}, 60);

