function expectConfigError(label, target, body) {
  if (body !== undefined) {
    fs.writeFileSync(target, body);
  }
  try {
    loadConfig(target);
  } catch (err) {
    assert.ok(err instanceof ConfigError, `${label}: expected ConfigError, got ${err}`);
    assert.ok(typeof err.path === "string" && err.path.length > 0, `${label}: .path missing`);
    assert.ok(typeof err.reason === "string" && err.reason.length > 0, `${label}: .reason missing`);
