"use strict";

function median(values) {
  if (values.length === 0) {
    throw new Error("median() requires at least one value");
  }
  if (values.length % 2 === 1) {
    return values[(values.length - 1) / 2];
  }
  return (values[values.length / 2 - 1] + values[values.length / 2]) / 2;
}

